        [
          buildParam(0, RouteParamtypes.PARAM, 'abc', [plainErrorPipe]),
          buildParam(1, RouteParamtypes.QUERY, 'x', [throwingPipe('B')]),
        ],
        true,
      )!;

      await expect(
        pipesFn([undefined, undefined], {}, {}, () => {}),
      ).rejects.toThrow('boom');
    });

